SELECT mb.message_id, mb.user_id, mb.message, mb.message_type, mb.create_dt,
ut.nickname, ut.profile_img_url, mb.crew_id FROM message_tb mb INNER JOIN user_tb ut ON (mb.user_id = ut.user_id) WHERE mb.crew_id = #{crewId}
AND mb.create_dt >= ( SELECT create_dt FROM crew_user_tb WHERE user_id = #{userId} AND crew_id = #{crewId} ) AND mb.message_id <= #{prevCursorId} ORDER BY
mb.message_id DESC LIMIT #{size}

SELECT mb.message_id, mb.user_id, mb.message, mb.message_type, mb.create_dt,
ut.nickname, ut.profile_img_url, mb.crew_id FROM message_tb mb INNER JOIN user_tb ut ON (mb.user_id = ut.user_id) WHERE mb.crew_id = #{crewId}
AND mb.create_dt >= ( SELECT create_dt FROM crew_user_tb WHERE user_id = #{userId} AND crew_id = #{crewId} ) AND mb.message_id >= #{nextCursorId} ORDER BY mb.message_id ASC LIMIT #{size}
